	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec);
	// C: j x m
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec);
	// D: m x l
	DEFINE_PROTO_STRUCT(d_layout, l_vec ^ m_vec);
	// E: i x j
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);
	// F: j x l
	DEFINE_PROTO_STRUCT(f_layout, l_vec ^ j_vec);
	// G: i x l
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto B, auto C, auto D) {
	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	auto ni = A | get_length<'i'>();
	auto nk = A | get_length<'k'>();
	auto nj = B | get_length<'j'>();
	auto nm = C | get_length<'m'>();
	auto nl = D | get_length<'l'>();

	// Precompute reciprocals of denominators to avoid repeated divisions
	const num_t inv_5ni = num_t(1) / num_t(5 * ni);
	const num_t inv_5nj = num_t(1) / num_t(5 * nj);
	const num_t inv_5nl = num_t(1) / num_t(5 * nl);
	const num_t inv_5nk = num_t(1) / num_t(5 * nk);

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	// Traverse all (i,k) once; each element does only inexpensive integer ops + one multiply.
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		std::size_t num = (i * k + 1) % ni;
		A[state] = static_cast<num_t>(num) * inv_5ni;
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		std::size_t num = (k * (j + 1) + 2) % nj;
		B[state] = static_cast<num_t>(num) * inv_5nj;
	});

	// C[j][m] = (j * (m + 3) % nl) / (5 * nl)
	traverser(C).for_each([=](auto state) {
		auto [j, m] = get_indices<'j', 'm'>(state);
		std::size_t num = (j * (m + 3) % nl);
		C[state] = static_cast<num_t>(num) * inv_5nl;
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	traverser(D).for_each([=](auto state) {
		auto [m, l] = get_indices<'m', 'l'>(state);
		std::size_t num = (m * (l + 2) + 2) % nk;
		D[state] = static_cast<num_t>(num) * inv_5nk;
	});

	(void)nm; // nm is intentionally unused, keep to match original semantics
}

// computation kernel
//
// Optimized triple matrix multiplication:
//
//   E = A * B   (E: i x j, A: i x k, B: k x j)
//   F = C * D   (F: j x l, C: j x m, D: m x l)
//   G = E * F   (G: i x l, E: i x j, F: j x l)
//
// The traverser-based loop nests are ordered to improve data locality:
//
//  - For E: outer loop over i, then k, inner over j
//      -> A(i,k) used as a scalar for a whole row of B(k,*) and E(i,*)
//         which are both contiguous in 'j'.
//  - For F: outer loop over j, then m, inner over l
//      -> C(j,m) used as a scalar for a whole row of D(m,*) and F(j,*),
//         both contiguous in 'l'.
//  - For G: outer loop over i, then j, inner over l
//      -> E(i,j) used as a scalar for a whole row of F(j,*) and G(i,*),
//         both contiguous in 'l'.
//
// Each output row is zero-initialized once per outer i/j, so we do not need
// separate passes just to clear E, F, and G.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// E := A * B
	// Layouts:
	//   A: dims 'i','k'  (k is inner)
	//   B: dims 'k','j'  (j is inner)
	//   E: dims 'i','j'  (j is inner)
	// We iterate i (rows of E / A), then:
	//    - zero E(i, :)
	//    - for each k, use A(i,k) as a scalar and traverse j contiguously
	//      for both B(k, :) and E(i, :)
	// ---------------------------------------------------------------------
	traverser(E, A, B).template for_dims<'i'>([&](auto trav_i) {
		// Zero the whole row E(i, :)
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			E[trav_ij] = static_cast<num_t>(0.0);
		});

		// Accumulate over k
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// A(i,k) is invariant for all j in this inner loop
			const num_t a_ik = A[trav_ik];

			// Traverse all columns j for this (i,k)
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				E[trav_ikj] += a_ik * B[trav_ikj];
			});
		});
	});

	// ---------------------------------------------------------------------
	// F := C * D
	// Layouts:
	//   C: dims 'j','m'  (m is inner)
	//   D: dims 'm','l'  (l is inner)
	//   F: dims 'j','l'  (l is inner)
	// We iterate j (rows of F / C), then:
	//    - zero F(j, :)
	//    - for each m, use C(j,m) as a scalar and traverse l contiguously
	//      for both D(m, :) and F(j, :)
	// ---------------------------------------------------------------------
	traverser(F, C, D).template for_dims<'j'>([&](auto trav_j) {
		// Zero the whole row F(j, :)
		trav_j.template for_dims<'l'>([&](auto trav_jl) {
			F[trav_jl] = static_cast<num_t>(0.0);
		});

		// Accumulate over m
		trav_j.template for_dims<'m'>([&](auto trav_jm) {
			// C(j,m) is invariant for all l in this inner loop
			const num_t c_jm = C[trav_jm];

			// Traverse all columns l for this (j,m)
			trav_jm.template for_dims<'l'>([&](auto trav_jml) {
				F[trav_jml] += c_jm * D[trav_jml];
			});
		});
	});

	// ---------------------------------------------------------------------
	// G := E * F
	// Layouts:
	//   E: dims 'i','j'  (j is inner)
	//   F: dims 'j','l'  (l is inner)
	//   G: dims 'i','l'  (l is inner)
	// We iterate i (rows of G / E), then:
	//    - zero G(i, :)
	//    - for each j, use E(i,j) as a scalar and traverse l contiguously
	//      for both F(j, :) and G(i, :)
	// ---------------------------------------------------------------------
	traverser(G, E, F).template for_dims<'i'>([&](auto trav_i) {
		// Zero the whole row G(i, :)
		trav_i.template for_dims<'l'>([&](auto trav_il) {
			G[trav_il] = static_cast<num_t>(0.0);
		});

		// Accumulate over j
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// E(i,j) is invariant for all l in this inner loop
			const num_t e_ij = E[trav_ij];

			// Traverse all columns l for this (i,j)
			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				G[trav_ijl] += e_ij * F[trav_ijl];
			});
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

