	// F := C * D   (F: j x l, C: j x m, D: m x l)
	// ---------------------------------------------------------------------

	// 1) Zero F
	traverser(F).for_each([&](auto s) {
		F[s] = (num_t)0.0;
	});

	// 2) Accumulate in JML order:
	//    for j
	//      for m
	//        for l
	//
	// Inner loop runs over 'l', which is contiguous in both F(j,l) and D(m,l);
	// C(j,m) is held in a register across all l.
