	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	const auto ni = A | get_length<'i'>();
	const auto nk = A | get_length<'k'>();
	const auto nj = B | get_length<'j'>();
	const auto nm = C | get_length<'m'>();
	const auto nl = D | get_length<'l'>();

