	// D layout is 'l' (outer) x 'm' (inner); iterate 'l' then 'm' to write
	// contiguously in 'm'.
	traverser(D).template for_dims<'l', 'm'>([=](auto trav) {
		auto state = trav.state();
		auto [l, m] = get_indices<'l', 'm'>(state);

		const auto num = (m * (l + std::size_t(2)) + std::size_t(2)) % nk;
		D[state] = num_t(num) * inv_5nk;
	});
}

// computation kernel
// - Uses local accumulators for E and F to avoid repeated loads/stores.
// - Reorders the G = E * F multiplication to an i–j–l loop nest so that
//   F is accessed along its contiguous 'l' dimension and G rows are
//   updated in a streaming fashion.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop
	// ------------------------------------------------------------------
	// E := A * B
	// ------------------------------------------------------------------
	// Original semantics:
	//   E[i][j] = sum_k A[i][k] * B[k][j]
	//
	// Optimization:
	//   - Accumulate into a local scalar 'sum' and store once per (i,j)
	//     instead of repeatedly reading/writing E[i][j] inside the k-loop.
	traverser(E, A, B).template for_dims<'i', 'j'>([&](auto trav_ij) {
		num_t sum = num_t(0);

		trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
			sum += A[trav_ijk] * B[trav_ijk];
		});

		E[trav_ij] = sum;
	});

	// ------------------------------------------------------------------
	// F := C * D
	// ------------------------------------------------------------------
	// Original semantics:
	//   F[j][l] = sum_m C[j][m] * D[m][l]
	//
	// Same optimization pattern as for E.
	traverser(F, C, D).template for_dims<'j', 'l'>([&](auto trav_jl) {
		num_t sum = num_t(0);

		trav_jl.template for_dims<'m'>([&](auto trav_jlm) {
			sum += C[trav_jlm] * D[trav_jlm];
		});

		F[trav_jl] = sum;
	});

	// ------------------------------------------------------------------
	// G := E * F
	// ------------------------------------------------------------------
	// Original semantics:
	//   for all i, l:
	//     G[i][l] = 0;
	//     for all j:
	//       G[i][l] += E[i][j] * F[j][l];
	//
	// We preserve this mathematically, but change the loop ordering:
	//   1. Initialize all G[i][l] to 0 in a separate pass.
	//   2. Use an i–j–l nest:
	//        for i
	//          for j
	//            let e_ij = E[i][j];
	//            for l
	//              G[i][l] += e_ij * F[j][l];
	//
	// Rationale:
	//   - E is laid out as i x j with 'j' being the inner dimension.
	//     Iterating (i,j) first accesses E contiguously along 'j'.
	//   - F is laid out as j x l with 'l' being the inner dimension.
	//     Inner-most 'l' loop accesses F contiguously along 'l'.
	//   - G is laid out as i x l with 'l' inner; the inner-most 'l'
	//     loop updates G rows in a streaming fashion.
	//   - Each E[i][j] is loaded once and reused across all l for that
	//     (i,j) pair, reducing memory traffic.
	//
	// Step 1: zero G.
	traverser(G).for_each([&](auto state) {
		G[state] = num_t(0);
	});

	// Step 2: G = E * F with improved traversal order.
	traverser(G, E, F).template for_dims<'i', 'j'>([&](auto trav_ij) {
		// 'trav_ij' has 'i' and 'j' fixed; 'l' remains to be iterated.
		const num_t e_ij = E[trav_ij]; // load once per (i,j)

		// Iterate over 'l' (inner-most dimension for both F and G).
		trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
			G[trav_ijl] += e_ij * F[trav_ijl];
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

